import {balloonDraw} from './balloons.js?v=20261025-release1';
export function setupRetakeUI(){
 const $=id=>document.getElementById(id),select=$('balloonShape'),list=document.createElement('div');list.id='balloonPicker';list.setAttribute('role','listbox');list.setAttribute('aria-label','말풍선 모양 미리보기');select.after(list);select.hidden=true;
 const sync=()=>{for(const b of list.children){const on=b.dataset.value===select.value;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1;}};
 for(const option of select.options){const b=document.createElement('button'),cv=document.createElement('canvas'),name=document.createElement('span');b.type='button';b.dataset.value=option.value;b.setAttribute('role','option');b.setAttribute('aria-label',option.text);cv.width=160;cv.height=60;name.textContent=option.text;balloonDraw(cv.getContext('2d'),{x:.08,y:.1,w:.82,h:.65,shape:option.value,line:14,text:option.value==='text'?'대사':'',font:100,tail:option.value==='text'?'none':'straight'},160,60);b.append(cv,name);b.onclick=()=>{select.value=option.value;select.dispatchEvent(new Event('change'));sync();};list.append(b);}
 list.onkeydown=e=>{if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();const all=[...list.children],i=all.indexOf(document.activeElement),b=all[(i+(e.key==='ArrowDown'?1:-1)+all.length)%all.length];b.click();b.focus();};select.addEventListener('change',sync);select.addEventListener('balloon-shape-sync',sync);document.addEventListener('tool-change',sync);sync();
 // Editing tint is an overlay outside the selected cut, never saved artwork.
 const paper=$('paper'),ns='http://www.w3.org/2000/svg',shade=document.createElementNS(ns,'svg'),path=document.createElementNS(ns,'path');shade.id='cutEditingShade';shade.setAttribute('aria-hidden','true');path.setAttribute('fill-rule','evenodd');shade.append(path);let scheduled=false;
 const update=()=>{scheduled=false;const cut=paper.querySelector('.panel-wrap.selected:not(.page-base):not(.frame-committed)');shade.style.display=!cut||document.body.classList.contains('recognizing-panels')?'none':'';if(!cut){shade.remove();return;}if(shade.parentElement!==paper)paper.append(shade);const w=paper.clientWidth,h=paper.clientHeight,x=cut.offsetLeft,y=cut.offsetTop,cw=cut.clientWidth,ch=cut.clientHeight;shade.setAttribute('viewBox',`0 0 ${w} ${h}`);const polygon=cut.querySelector('.frame-selection polygon')?.getAttribute('points');const points=polygon?polygon.trim().split(/\s+/).map(p=>p.split(',').map(Number)).map(([a,b])=>[x+a*cw/100,y+b*ch/100]):[[x,y],[x+cw,y],[x+cw,y+ch],[x,y+ch]];path.setAttribute('d',`M0 0H${w}V${h}H0Z M${points.map(p=>p.join(' ')).join('L')}Z`);};
 const schedule=()=>{if(!scheduled){scheduled=true;requestAnimationFrame(update);}};new MutationObserver(rs=>{if(rs.some(r=>r.target!==shade&&!shade.contains(r.target)))schedule();}).observe(paper,{childList:true,subtree:true,attributes:true,attributeFilter:['class','style']});new ResizeObserver(schedule).observe(paper);document.addEventListener('tool-change',schedule);schedule();
}
